CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
CREATE TABLE public.transport_commission_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), created_by uuid NOT NULL DEFAULT auth.uid(), min_weight numeric(14,3) NOT NULL CHECK(min_weight>=0), max_weight numeric(14,3), amount numeric(14,2) NOT NULL CHECK(amount>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(max_weight IS NULL OR max_weight>min_weight));
GRANT SELECT, INSERT, UPDATE ON public.transport_commission_rules TO authenticated;
GRANT ALL ON public.transport_commission_rules TO service_role;
ALTER TABLE public.transport_commission_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY transport_rules_select ON public.transport_commission_rules FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_organizations u WHERE u.user_id=auth.uid() AND u.organization_id=transport_commission_rules.organization_id) AND (public.has_role(auth.uid(),'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.user_module_permissions p WHERE p.user_id=auth.uid() AND p.module_name='loads' AND p.can_view)));
CREATE POLICY transport_rules_insert ON public.transport_commission_rules FOR INSERT TO authenticated WITH CHECK (created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.user_organizations u WHERE u.user_id=auth.uid() AND u.organization_id=transport_commission_rules.organization_id) AND (public.has_role(auth.uid(),'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.user_module_permissions p WHERE p.user_id=auth.uid() AND p.module_name='loads' AND p.can_create)));
CREATE POLICY transport_rules_update ON public.transport_commission_rules FOR UPDATE TO authenticated USING (EXISTS(SELECT 1 FROM public.user_organizations u WHERE u.user_id=auth.uid() AND u.organization_id=transport_commission_rules.organization_id) AND (public.has_role(auth.uid(),'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.user_module_permissions p WHERE p.user_id=auth.uid() AND p.module_name='loads' AND p.can_create))) WITH CHECK (EXISTS(SELECT 1 FROM public.user_organizations u WHERE u.user_id=auth.uid() AND u.organization_id=transport_commission_rules.organization_id) AND (public.has_role(auth.uid(),'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.user_module_permissions p WHERE p.user_id=auth.uid() AND p.module_name='loads' AND p.can_create)));
ALTER TABLE public.transport_commission_rules ADD CONSTRAINT transport_rules_no_overlap EXCLUDE USING gist (organization_id extensions.gist_uuid_ops WITH =, numrange(min_weight,max_weight,'[)') WITH &&);
CREATE OR REPLACE FUNCTION public.apply_transport_commission() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE calculated numeric; BEGIN SELECT amount INTO calculated FROM public.transport_commission_rules WHERE organization_id=NEW.organization_id AND NEW.delivery_weight>=min_weight AND (max_weight IS NULL OR NEW.delivery_weight<max_weight); IF calculated IS NULL THEN RAISE EXCEPTION 'لا يوجد شرط عمولة يغطي وزن الحمولة'; END IF; NEW.commission:=calculated; RETURN NEW; END; $$;
CREATE TRIGGER transport_load_commission BEFORE INSERT ON public.transport_loads FOR EACH ROW EXECUTE FUNCTION public.apply_transport_commission();